Translate("zhCN", "western-plaguelands", {
	title = "西瘟疫之地",
	aliases = { "西瘟疫之地" },
	sections = {
		{
			title = "概述",
			text = [=[西瘟疫之地曾是{link:lordaeron}洛丹伦{/link}北方的腹地：在{link:tirisfal-glades}提瑞斯法{/link}的{link:moonglade}林地{/link}与东流的河水之间，连绵着农田、果园、粮仓和富足的城镇。如今这里是一片灰暗而有毒的土地。青草枯萎，树木光秃，曾经养活一个王国的田野，如今只供养{link:scourge}天灾军团{/link}。巨大的药锅在旧日农庄上空吐出瘟疫。亡者在道路上游荡。然而这片土地并未彻底沦丧。三方势力前来与亡者争夺它：南面的{link:alliance}联盟{/link}，西面的{link:forsaken}被遗忘者{/link}，以及据守{link:northwatch-hold}北方要塞{/link}的{link:scarlet-crusade}血色十字军{/link}。三者互不信任。]=],
		},
		{
			title = "起源",
			text = [=[没有任何编年史记载这片土地最初在哪一年有人定居。只要{link:lordaeron}洛丹伦{/link}王国存在一天，这里就属于它，而且是王国最富饶的地区之一。{link:ruins-of-andorhal}安多哈尔{/link}城将北方的收成汇集于自己的粮仓。{link:hearthglen}壁炉谷{/link}镇和玛登霍尔德城堡守卫着北方的丘陵；{link:second-war}第二次战争{/link}之后的岁月里，统治这里的是{link:tirion-fordring}提里奥·弗丁{/link}，一位白银之手的领主和圣骑士。在南方，巴罗夫家族拥有静谧湖中的岛上城堡{link:caer-darrow}凯尔达隆{/link}，王国的贵族常去那里休憩，在水边请人为自己画像。]=],
		},
		{
			title = "当今",
			text = [=[{link:scourge}天灾军团{/link}至今仍统治着西瘟疫之地。一个名叫{link:araj-the-summoner}召唤者阿拉基{/link}的巫妖占据着{link:ruins-of-andorhal}安多哈尔{/link}的废墟。四口瘟疫药锅由药锅领主看守，毒害着农田。在南方的{link:caer-darrow}凯尔达隆{/link}之下，教派在通灵学院中训练它的死灵法师。

与之对抗的，是这片土地边缘的几支小小力量。在南方的{link:chillwind-camp}寒风营地{/link}，{link:commander-ashlam-valorfist}指挥官阿什拉姆·瓦罗菲斯特{/link}以{link:kingdom-of-stormwind}暴风王国{/link}的名义，召集{link:alliance}联盟{/link}的士兵与勇士。在西方的{link:the-bulwark}亡灵壁垒{/link}，{link:high-executor-derrington}高级执行官德灵顿{/link}为{link:forsaken}被遗忘者{/link}和{link:horde}部落{/link}守卫着{link:tirisfal-glades}提瑞斯法{/link}的东大门。在北方，{link:scarlet-crusade}血色十字军{/link}在{link:taelan-fordring}大领主泰兰·弗丁{/link}麾下据守{link:hearthglen}壁炉谷{/link}。它与天灾军团作战，也与其他所有人作战。{link:argent-dawn}银色黎明{/link}的使者在联盟与部落的营地中都有效力，他们对双方别无所求，只求共同对抗亡者。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:scourge}天灾军团{/link}。{/b}骷髅、食尸鬼、憎恶、幽灵，以及溺死者和被杀者不得安息的灵魂。它们占据着{link:ruins-of-andorhal}安多哈尔{/link}、{link:sorrow-hill}悔恨岭{/link}和旧日的农庄。
• {b}{link:cult-of-the-damned}诅咒教派{/link}。{/b}巫妖王的活人仆从，在安多哈尔和通灵学院中与亡者共事。
• {b}{link:alliance}联盟{/link}。{/b}驻守{link:chillwind-camp}寒风营地{/link}的{link:stormwind-city}暴风城{/link}士兵、牧师、炼{link:ginro-hearthkindle}金{/link}师和{link:si-7}军情七处{/link}的特工。
• {b}{link:forsaken}被遗忘者{/link}。{/b}{link:the-bulwark}亡灵壁垒{/link}的守军，为{link:sylvanas-windrunner}黑暗女王{/link}守卫边境。
• {b}{link:scarlet-crusade}血色十字军{/link}。{/b}{link:hearthglen}壁炉谷{/link}的骑士、牧师和审判官，以及他们在北山夺取的伐木场中的工人。
• {b}{link:argent-dawn}银色黎明{/link}。{/b}驻扎在双方营地中的军官和守卫者。
• {b}旧王国不得安息的亡者。{/b}从未成为天灾军团一员的鬼魂：{link:caer-darrow}凯尔达隆{/link}的亡灵，{link:felstone-field}费尔斯通农场{/link}的那个女人，悔恨岭的哀悼者。
• {b}染疫的野兽。{/b}狼、熊、蝙蝠和秃鹫，与这片土地患着同样的瘟疫。]=],
		},
		{
			title = "历史",
			text = [=[• {b}王国。{/b}世世代代，这里都是{link:lordaeron}洛丹伦{/link}的农田和河畔城镇，在王国的庇护下富足而安宁。
• {b}{link:second-war}第二次战争{/link}。{/b}{link:orcs}兽人{/link}{link:horde}部落{/link}入侵北方时，白银之手的骑士们出兵迎战。{link:tirion-fordring}提里奥·弗丁{/link}也在其中。战后他统治{link:hearthglen}壁炉谷{/link}周围的土地，直到因饶恕一个兽人的性命而被剥夺封地。
• {b}瘟疫。{/b}{link:third-war}第三次战争{/link}之前，{link:cult-of-the-damned}诅咒教派{/link}的爪牙污染了{link:ruins-of-andorhal}安多哈尔{/link}粮仓中的谷物，这些谷物又被运往北方的村庄。吃下谷物的人染病、死去，再作为巫妖王的仆从复起。{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子来到安多哈尔，杀死了教派的首领{link:kel-thuzad}克尔苏加德{/link}，但瘟疫早已蔓延到无可救治的地步，北方的城镇一个接一个地陷落。
• {b}{link:fall-of-lordaeron}洛丹伦的陷落{/link}。{/b}阿尔萨斯弑父之后，白银之手分崩离析。{link:uther-the-lightbringer}光明使者乌瑟尔{/link}死在自己学生的手中，人们在这片土地上为他修建了一座陵墓。{link:caer-darrow}凯尔达隆{/link}的巴罗夫家族将城堡献给了教派，通灵学院便建在城堡的地穴中。
• {b}当今。{/b}{link:scourge}天灾军团{/link}占据着这片土地的中心。生者固守边缘，十字军占据北方。]=],
		},
		{
			title = "瘟疫之地传说",
			text = [=[• {link:ruins-of-andorhal}安多哈尔{/link}的怀表，以及市政厅废墟上的大钟，全都停在同一时刻。那正是瘟疫最初吞噬这座城市的时刻。
• 据说在{link:caer-darrow}凯尔达隆{/link}岛上，镇民的鬼魂一遍又一遍地重温他们最后一个快乐的日子，仿佛什么都不曾发生。
• {link:forsaken}被遗忘者{/link}和{link:alliance}联盟{/link}都说自己将夺取安多哈尔。谁也没有说过，夺下之后要如何处置这座城市。
• {link:sorrow-hill}悔恨岭{/link}的亡者中，有许多人是在保卫东面的{link:darrowshire}达隆郡{/link}时倒下的。]=],
		},
	},
})

Translate("zhCN", "chillwind-camp", {
	title = "寒风营地",
	sections = {
		{
			title = "概述",
			text = [=[寒风营地是{link:alliance}联盟{/link}在{link:western-plaguelands}西瘟疫之地{/link}的立足点。它位于这片土地的南缘，俯临{link:alterac-mountains}奥特兰克{/link}的{link:razorfen-downs}高地{/link}，几顶帐篷、一座锻炉和一处狮鹫栖架紧贴在山坡上。{link:commander-ashlam-valorfist}指挥官阿什拉姆·瓦罗菲斯特{/link}在这里以{link:kingdom-of-stormwind}暴风城{/link}的名义筹划对{link:ruins-of-andorhal}安多哈尔{/link}的战争。他的牧师研究瘟疫，他的炼{link:ginro-hearthkindle}金{/link}师研究通灵学院，一名{link:si-7}军情七处{/link}的特工在此等待东方的消息。{link:argent-dawn}银色黎明{/link}的军官也在他们当中设有驻所。{link:weldon-barov}维尔顿·巴罗夫{/link}，他的家族中最后一位在世的领主，也在营地的庇护下住在这里。]=],
		},
	},
})

Translate("zhCN", "the-bulwark", {
	title = "亡灵壁垒",
	aliases = { "壁垒" },
	sections = {
		{
			title = "概述",
			text = [=[亡灵壁垒是{link:tirisfal-glades}提瑞斯法{/link}与瘟疫之地之间的设防大门。它的城墙和塔楼是为了把{link:scourge}天灾军团{/link}挡在{link:forsaken}被遗忘者{/link}的领土之外而建的，如今驻守在此的正是被遗忘者。{link:high-executor-derrington}高级执行官德灵顿{/link}在此指挥。他从壁垒派兵东进，攻打{link:ruins-of-andorhal}安多哈尔{/link}和瘟疫药锅；又派兵北上，对抗{link:scarlet-crusade}血色十字军{/link}。药剂师和暗影牧师与他的士兵并肩工作。{link:argent-dawn}银色黎明{/link}也在大门派驻了军官。{link:alexi-barov}阿莱克斯·巴罗夫{/link}同样在此，他是一个没落家族的被遗忘者领主，正在这里等待家族财产的消息。]=],
		},
	},
})

Translate("zhCN", "ruins-of-andorhal", {
	title = "安多哈尔废墟",
	aliases = { "安多哈尔" },
	sections = {
		{
			title = "概述",
			text = [=[安多哈尔曾是{link:lordaeron}洛丹伦{/link}北方的大粮仓之城。王国的收成储存在它的粮仓里，{link:cult-of-the-damned}诅咒教派{/link}也正是从这里送出了引发瘟疫的污染谷物。{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子在此将{link:kel-thuzad}克尔苏加德{/link}逼入绝境并杀死了他。如今这座城市是一片被{link:scourge}天灾军团{/link}占据的废墟。四座哨塔守卫着通往城市的道路，巫妖{link:araj-the-summoner}召唤者阿拉基{/link}在城市中心坐镇。安多哈尔的每一座钟都停在瘟疫吞噬它的那一刻。在城市西北角的旅店废墟里，一个名叫{link:chromie}克罗米{/link}的奇怪{link:gnomes}侏儒{/link}女子安了家。]=],
		},
	},
})

Translate("zhCN", "hearthglen", {
	title = "壁炉谷",
	sections = {
		{
			title = "概述",
			text = [=[壁炉谷坐落在遥远北方的丘陵上，俯瞰着瘟疫之地。它曾是{link:tirion-fordring}提里奥·弗丁{/link}的城镇，他在玛登霍尔德城堡统治这片土地，直到遭到放逐。在对抗{link:scourge}天灾军团{/link}的战争中，{link:arthas-menethil}阿尔萨斯·米奈希尔{/link}王子曾在壁炉谷抵御亡者，直到{link:uther-the-lightbringer}乌瑟尔{/link}前来解围。如今这座城镇属于{link:scarlet-crusade}血色十字军{/link}。十字军战士在城墙上巡逻，城堡是{link:taelan-fordring}大领主泰兰·弗丁{/link}的驻地，通往城镇的道路由壁炉谷山道沿线的前哨监视。十字军对这座城镇戒备森严。{link:stormwind-city}暴风城{/link}中有人认为，它的重要性远不止于历史。]=],
		},
	},
})

Translate("zhCN", "northridge-lumber-camp", {
	title = "北山伐木场",
	aliases = { "北山锯木厂" },
	sections = {
		{
			title = "概述",
			text = [=[北山伐木场位于{link:hearthglen}壁炉谷{/link}以南，在通往城镇的上山道路西侧。瘟疫之前，这里是一座锯木厂，北方的人家在此砍伐、锯切山中的木材，挣得口粮。{link:scarlet-crusade}血色十字军{/link}夺取了它。如今十字军的工人和伐木工在工头的监视下，为壁炉谷的城墙伐木。曾在这里劳作的人家的儿子们没有忘记。一个在{link:chillwind-camp}寒风营地{/link}为{link:alliance}联盟{/link}效力，另一个在{link:the-bulwark}亡灵壁垒{/link}为{link:forsaken}被遗忘者{/link}效力，两人都宁愿毁掉这座伐木场，也不愿让它留在十字军手中。]=],
		},
	},
})

Translate("zhCN", "felstone-field", {
	title = "费尔斯通农场",
	sections = {
		{
			title = "概述",
			text = [=[费尔斯通农场是费尔斯通一家的农庄，位于{link:ruins-of-andorhal}安多哈尔{/link}西北。房屋仍在，谷仓也仍在，但田地如今为{link:scourge}天灾军团{/link}所用。一口瘟疫药锅矗立在田间，由药锅领主胆汁之喉和最生疏的亡者看守。农舍楼上的房间里，徘徊着{link:janice-felstone}詹妮丝·费尔斯通{/link}的鬼魂。她不知道自己已在那里等了多久。她说起一个本想寄出的包裹，说起她的丈夫约翰，仿佛瘟疫昨天才刚刚降临。]=],
		},
	},
})

Translate("zhCN", "dalson-s-tears", {
	title = "达尔松之泪",
	sections = {
		{
			title = "概述",
			text = [=[达尔松之泪几乎就在{link:ruins-of-andorhal}安多哈尔{/link}正北。这里曾是{link:dar}达尔{/link}松一家的农庄，如今的名字是瘟疫之后才有的。{link:scourge}天灾军团{/link}的一口药锅立在田里。农舍里有一本日记，停在最后一页；一个柜子布满绝望的抓痕；还有一间茅厕，门被人从里面撞得残破不堪。一具骷髅在院子里游荡。这些东西讲述的故事，是瘟疫之地最悲伤的故事之一。]=],
		},
	},
})

Translate("zhCN", "the-writhing-haunt", {
	title = "嚎哭鬼屋",
	aliases = { "嚎哭鬼屋" },
	sections = {
		{
			title = "概述",
			text = [=[嚎哭鬼屋是{link:ruins-of-andorhal}安多哈尔{/link}以东的一座荒废农庄，紧邻城市残破的城墙。{link:scourge}天灾军团{/link}在这里竖起了一口瘟疫药锅，周围的土地上亡者涌动。农庄的一间小屋里躺着一位{link:tauren}牛头人{/link}德鲁伊，他从远方赶来，想要医治这片土地上的野兽。他没有找到解药，自己也染上了瘟疫。]=],
		},
	},
})

Translate("zhCN", "gahrron-s-withering", {
	title = "盖罗恩农场",
	sections = {
		{
			title = "概述",
			text = [=[盖罗恩农场是{link:western-plaguelands}西瘟疫之地{/link}东北部的一座死去的农庄，靠近{link:eastern-plaguelands}东瘟疫之地{/link}的边界。西部四口药锅中的最后一口就立在这里。守卫它的是幽灵和鬼魂，它们是这片土地上{link:scourge}天灾军团{/link}最危险的仆从之一；还有药锅领主魂怒。没有任何记载说明盖罗恩是谁，也没有说明农庄的人们后来怎样了。]=],
		},
	},
})

Translate("zhCN", "sorrow-hill", {
	title = "悔恨岭",
	sections = {
		{
			title = "概述",
			text = [=[悔恨岭是瘟疫之地南部的大墓地，位于{link:chillwind-camp}寒风营地{/link}与{link:ruins-of-andorhal}安多哈尔{/link}之间。山坡上布满坟墓、墓穴和纪念碑，其中就有{link:uther-the-lightbringer}光明使者乌瑟尔{/link}的陵墓。亡者在这里不得安息。骷髅和食尸鬼从坟墓中大批爬起，{link:scourge}天灾军团{/link}便把这座山岭当作一道活的城墙，挡在通往安多哈尔的东路之前。{link:marlene-redpath}玛莱恩·雷德帕斯{/link}的鬼魂在墓碑之间行走，她仍在打听她在{link:darrowshire}达隆郡{/link}之战中藏起来的侄女的消息。]=],
		},
	},
})

Translate("zhCN", "uther-s-tomb", {
	title = "乌瑟尔之墓",
	sections = {
		{
			title = "概述",
			text = [=[乌瑟尔之墓坐落在{link:sorrow-hill}悔恨岭{/link}上，是一座为纪念白银之手第一位圣骑士{link:uther-the-lightbringer}光明使者乌瑟尔{/link}而建的石殿。殿内立着光明使者的巨大雕像。这是瘟疫之地上少数仍由生者守护的地方之一。{link:high-priest-thel-danis}高阶牧师赛尔丹尼斯{/link}守卫着陵墓，并净化亡者之石上的邪恶。一个名叫{link:myranda-the-hag}米兰达{/link}的老妇人也住在那里。她曾是{link:tirion-fordring}提里奥·弗丁{/link}信赖的谋士。]=],
		},
	},
})

Translate("zhCN", "caer-darrow", {
	title = "凯尔达隆",
	aliases = { "达隆米尔湖" },
	sections = {
		{
			title = "概述",
			text = [=[凯尔达隆是达隆米尔湖上的一座岛上城堡，位于{link:western-plaguelands}西瘟疫之地{/link}的东南部。世世代代，它都是巴罗夫家族的居所，也是{link:lordaeron}洛丹伦{/link}贵族前来水边休憩的宜人之地。巴罗夫家族把它献给了{link:cult-of-the-damned}诅咒教派{/link}。教派在城堡下的地穴中建立了它的死灵学院——通灵学院。城堡周围的小镇已没有生者。鬼魂留了下来：市民、卫兵、一个面包师和他的孩子们、岸边的一位画家。他们大多一遍又一遍地重温最后一个快乐的日子。少数几个记得一切，他们希望学院被摧毁。]=],
		},
	},
})

Translate("zhCN", "taelan-fordring", {
	title = "泰兰·弗丁",
