			title = "骑士团的覆灭",
			text = [=[泰兰追随父亲的道路，加入了白银之手骑士团。当{link:uther-the-lightbringer}乌瑟尔{/link}倒下、骑士团瓦解时，他与最后的骑士们并肩作战。在{link:northdale}北谷{/link}村，他进行了最后的抵抗。在那里，他在绝望中扔下白银之手的旗帜，宣布脱离骑士团。他转而加入{link:scarlet-crusade}血色十字军{/link}，并在其中身居高位。]=],
		},
		{
			title = "事迹",
			text = [=[• 他受训成为白银之手的圣骑士。
• 他在{link:lordaeron}洛丹伦{/link}陷落时与{link:scourge}天灾军团{/link}作战，并在{link:northdale}北谷{/link}进行了最后的抵抗。
• 他脱离白银之手，加入了{link:scarlet-crusade}血色十字军{/link}。
• 他以大领主的身份在{link:hearthglen}壁炉谷{/link}指挥十字军。]=],
		},
	},
	chapters = {
