			title = "意义",
			text = [=[瓦罗菲斯特是{link:alliance}联盟{/link}在{link:lordaeron}洛丹伦{/link}{link:the-dead-acre}死亡之地{/link}上的利剑。他的战役是王国陷落以来，{link:stormwind-city}暴风城{/link}第一次真正在{link:scourge}天灾军团{/link}自己的地盘上向它出击。]=],
		},
