			text = [=[通往{link:ruins-of-andorhal}安多哈尔{/link}的西路和北路防守太严。瓦罗菲斯特选择了东路。要到达那里，他的部队必须经过{link:sorrow-hill}悔恨岭{/link}，那里的亡者成百上千地从坟墓中爬起。他的战役的第一击，就是在墓碑之间打响的。]=],
		},
		{
			title = "哨塔",
			hint = "标记安多哈尔的塔楼，以备进攻。",
			text = [=[{link:scourge}天灾军团{/link}利用四座哨塔指引它在{link:ruins-of-andorhal}安多哈尔{/link}的部队。瓦罗菲斯特命人制作了一支信标火把，用它把塔楼一座一座地标记出来。他的牧师感觉到信标在熊熊燃烧。指挥官宣布，把战斗带进城中的时候到了。]=],
		},
		{
			title = "药锅",
			hint = "帮助指挥官的牧师把瘟疫药锅转而用来对付天灾军团。",
			text = [=[药锅无法摧毁。{link:kel-thuzad}克尔苏加德{/link}的死灵魔法太过强大。于是，瓦罗菲斯特的副手{link:high-priestess-macdonnell}高阶牧师玛多妮尔{/link}计划改变药锅里熬制的东西。西部的四口药锅全被打开，毒液被取样，一种反制药剂被制成。完成之后，指挥官站在营地众人面前，高声感谢完成这件事的勇士，称其为{link:alliance}联盟{/link}的英雄。]=],
		},
		{
			title = "哀哉，安多哈尔",
			hint = "消灭统治安多哈尔的巫妖。",
			text = [=[最终，瓦罗菲斯特派他的勇士深入{link:ruins-of-andorhal}安多哈尔{/link}的中心，对付巫妖{link:araj-the-summoner}召唤者阿拉基{/link}。他们带回了巫妖护命匣的一块碎片。指挥官称之为一场将永载史册的胜利。]=],
		},
	},
	mentions = {
