Translate("zhCN", "chromie", {
	title = "克罗米",
	subtitle = "奇怪的历史学家",
	found = "安多哈尔西北角的旅店废墟",
	hint = "寻找住在安多哈尔旅店废墟中的侏儒女子。",
	allegiance = "未知",
	sections = {
		{
			title = "概述",
			text = [=[克罗米是一个矮小的{link:gnomes}侏儒{/link}女子，她在亡者占据的{link:ruins-of-andorhal}安多哈尔{/link}城中，把旅店废墟当成了自己的家。她住的房间完好得出奇，仿佛周围的毁灭从未触及它。她谈论时间，就像别人谈论天气。她会问旅人是不是从未来来的，而且看起来并不是在开玩笑。]=],
		},
		{
			title = "意义",
			text = [=[克罗米声称，有什么东西篡改了{link:ruins-of-andorhal}安多哈尔{/link}的时间之流，而她是来修补它的。不管她究竟是什么，她对这座城市的过去、对死于战争的人们的命运，都知道得远比一个{link:gnomes}侏儒{/link}应该知道的多。]=],
		},
		{
			title = "事迹",
			text = [=[• 她在{link:ruins-of-andorhal}安多哈尔{/link}的旅店废墟中住着一个房间。
• 她猎杀以城中破碎的时间之流为食的生物。
