	},
	chapters = {
		{
			title = "合二为一",
			hint = "让幸运符重新完整。",
			text = [=[包裹晚了许多年才送到收件人手中。詹妮丝的姐妹艾玛已成了{link:stormwind-city}暴风城{/link}街头的流浪者。她的兄弟耶利米已成了{link:forsaken}被遗忘者{/link}的一员，并改了名字。无论是谁收到了包裹，都把詹妮丝的那一半幸运符送了回来。另一半仍在农场上。当幸运符重新合而为一，放到她手中时，鬼魂的双眼清明起来。她自由了。]=],
